package domain

import (
	"crypto/rand"
	"time"

	"github.com/oklog/ulid/v2"
)

// ID is a ULID string generated by the client (design.md section 4), so
// machines can write without coordination and rows sort by creation time.
type ID = string

// IDGen produces new IDs. Injected so tests can be deterministic.
type IDGen interface {
	New(t time.Time) ID
}

// Clock returns the current time. Injected so tests can be deterministic.
type Clock interface {
	Now() time.Time
}

// ULIDGen is the production IDGen.
type ULIDGen struct{}

func (ULIDGen) New(t time.Time) ID {
	return ulid.MustNew(ulid.Timestamp(t), rand.Reader).String()
}

// SystemClock is the production Clock. Times are always UTC.
type SystemClock struct{}

func (SystemClock) Now() time.Time { return time.Now().UTC() }
